namespace PZWorkshopDownloader.Models;

/// <summary>
/// Tracks one download attempt for display on the Downloads tab. A new
/// entry is created each time a download starts (including retries), so
/// the tab doubles as a simple history log.
/// </summary>
public class DownloadTask : INotifyPropertyChanged
{
    public string Id { get; set; } = "";
    public string Title { get; set; } = "";

    private string _status = "Queued";
    public string Status
    {
        get => _status;
        set { _status = value; OnPropertyChanged(); }
    }

    // Latest SteamCMD output line, or a short result summary once finished.
    private string _detail = "";
    public string Detail
    {
        get => _detail;
        set { _detail = value; OnPropertyChanged(); }
    }

    private string _startedAt = "";
    public string StartedAt
    {
        get => _startedAt;
        set { _startedAt = value; OnPropertyChanged(); }
    }

    private string _finishedAt = "";
    public string FinishedAt
    {
        get => _finishedAt;
        set { _finishedAt = value; OnPropertyChanged(); }
    }

    // Batch 4: thumbnail path for the Downloads/History tiles, filled in
    // asynchronously once the download history has been loaded.
    private string _thumbnailPath = "";
    public string ThumbnailPath
    {
        get => _thumbnailPath;
        set { if (_thumbnailPath != value) { _thumbnailPath = value; OnPropertyChanged(); } }
    }

    public string Initial => Title.Length > 0 ? Title[..1].ToUpperInvariant() : "?";

    public event PropertyChangedEventHandler? PropertyChanged;

    protected void OnPropertyChanged([CallerMemberName] string? name = null) =>
        PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(name));
}

