/// <summary>
/// Clears the SteamCMD cached Workshop mod contents (steamapps/workshop/
/// content/108600/*). SteamCMD itself is left untouched; only the downloaded
/// mod folders go. Requires confirmation because it's not recoverable without
/// re-downloading each mod.
/// </summary>
private void ClearCache_Click(object sender, RoutedEventArgs e)
{
    var confirm = MessageBox.Show(
        "Clear the cached Workshop mods?\n\n" +
        "This deletes the mod folders SteamCMD downloaded to:\n\n" +
        SteamCmdService.GetCacheContentRoot() +
        "\n\nSteamCMD itself is not touched.",
        "Clear Cached Workshop Mods", MessageBoxButton.YesNo, MessageBoxImage.Warning);
    if (confirm != MessageBoxResult.Yes) return;

    try
    {
        int removed = SteamCmdService.ClearContentCache();
        AppendLog($"Cleared {removed} cached Workshop mod folder(s).");
        StatusText.Text = $"Cleared {removed} cached mod folder(s).";
    }
    catch (Exception ex)
    {
        AppendLog($"Failed to clear cached Workshop mods: {ex.Message}", "ERROR");
        MessageBox.Show("Could not clear the cache:\n" + ex.Message, "Clear Cached Workshop Mods",
            MessageBoxButton.OK, MessageBoxImage.Warning);
    }
}

