/// <summary>
/// The tile-size slider (and its label) only belongs in tile mode. The
/// tile-size resource is app-wide, so hiding the three sliders in one place
/// keeps every tab consistent.
/// </summary>
private void SetTileSliderVisibility(bool visible)
{
    var v = visible ? Visibility.Visible : Visibility.Collapsed;
    InstalledTileSlider.Visibility = v;
    InstalledTileSliderLabel.Visibility = v;
    DownloadsTileSlider.Visibility = v;
    DownloadsTileSliderLabel.Visibility = v;
    UninstalledTileSlider.Visibility = v;
    UninstalledTileSliderLabel.Visibility = v;
}

